import type { Quat, Vec3 } from '../contracts/math';
import type { IZone, ZoneBounds } from '../contracts/zones';
import type {
  FieldObstacle,
  ForceObstacle,
  HazardObstacle,
  Hole,
  MovingObstacle,
  ObstacleDescriptor,
  PadDescriptor,
  StaticObstacle,
} from '../courses/types';
import { GravityZone } from '../gameplay/zones/GravityZone';
import { KillZone } from '../gameplay/zones/KillZone';
import { LavaZone } from '../gameplay/zones/LavaZone';
import { MagnetZone } from '../gameplay/zones/MagnetZone';
import { WaterZone } from '../gameplay/zones/WaterZone';
import { ConveyorObstacle } from './conveyor';
import { FanObstacle } from './fan';
import type { MoverConfig, MoverKind } from './movers';
import { PadObstacle } from './pads';
import type { PadKind } from './pads';
import type { RotatingConfig, RotatingKind } from './rotating';
import { TeleporterObstacle } from './teleporter';
import type { BallObstacle } from './types';
import { normalizeVec3 } from './vec';
import type { BoxZone } from './zones';

/** Bridges authored hole data to the runtime obstacle, pad and zone implementations. */

const DOWN: Vec3 = { x: 0, y: -1, z: 0 };
const FORWARD: Vec3 = { x: 0, y: 0, z: 1 };

const ROTATING_KINDS: Partial<Record<MovingObstacle['type'], RotatingKind>> = {
  spinner: 'spinner',
  windmill: 'windmill',
  pendulum: 'pendulum',
};

const MOVER_KINDS: Partial<Record<MovingObstacle['type'], MoverKind>> = {
  platform: 'platform',
  'sliding-wall': 'sliding-wall',
  door: 'door',
  gate: 'door',
};

const PAD_KINDS: Record<PadDescriptor['type'], PadKind> = {
  'spring-pad': 'spring',
  'boost-pad': 'boost',
  'jump-pad': 'jump',
};

/** Obstacle volumes only ever rotate around Y, so the quaternion collapses to a yaw. */
function yawOf(rotation: Quat | undefined): number {
  if (!rotation) return 0;
  const { x, y, z, w } = rotation;
  return Math.atan2(2 * (w * y + x * z), 1 - 2 * (y * y + z * z));
}

function halfExtentsOf(obstacle: ObstacleDescriptor): Vec3 {
  const scale = obstacle.transform.scale;
  return {
    x: Math.abs(obstacle.size.x * (scale?.x ?? 1)) / 2,
    y: Math.abs(obstacle.size.y * (scale?.y ?? 1)) / 2,
    z: Math.abs(obstacle.size.z * (scale?.z ?? 1)) / 2,
  };
}

/** Oriented box the force obstacles and pads test the ball against. */
export function descriptorZone(obstacle: ObstacleDescriptor): BoxZone {
  return {
    shape: 'box',
    center: { ...obstacle.transform.position },
    halfExtents: halfExtentsOf(obstacle),
    rotationY: yawOf(obstacle.transform.rotation),
  };
}

/** Axis aligned bounds used by the gameplay zones, which never rotate. */
export function descriptorBounds(obstacle: ObstacleDescriptor): ZoneBounds {
  const center = obstacle.transform.position;
  const half = halfExtentsOf(obstacle);
  return {
    min: { x: center.x - half.x, y: center.y - half.y, z: center.z - half.z },
    max: { x: center.x + half.x, y: center.y + half.y, z: center.z + half.z },
  };
}

export function isForceObstacle(obstacle: ObstacleDescriptor): obstacle is ForceObstacle {
  return obstacle.type === 'teleporter' || obstacle.type === 'fan' || obstacle.type === 'conveyor';
}

export function isPadDescriptor(obstacle: ObstacleDescriptor): obstacle is PadDescriptor {
  return obstacle.type === 'spring-pad' || obstacle.type === 'boost-pad' || obstacle.type === 'jump-pad';
}

export function isFieldObstacle(obstacle: ObstacleDescriptor): obstacle is FieldObstacle {
  return obstacle.type === 'gravity-zone' || obstacle.type === 'magnet-zone';
}

export function isHazardObstacle(obstacle: ObstacleDescriptor): obstacle is HazardObstacle {
  return (
    obstacle.type === 'water' ||
    obstacle.type === 'void' ||
    obstacle.type === 'reset-zone' ||
    obstacle.type === 'lava'
  );
}

export function isMovingObstacle(obstacle: ObstacleDescriptor): obstacle is MovingObstacle {
  return 'motion' in obstacle;
}

export function createForceObstacle(descriptor: ForceObstacle): BallObstacle {
  const zone = descriptorZone(descriptor);
  if (descriptor.type === 'teleporter') {
    return new TeleporterObstacle({
      id: descriptor.id,
      kind: 'teleporter',
      enabled: descriptor.enabled,
      entryZone: zone,
      exitPosition: { ...descriptor.exit },
      exitVelocityScale: descriptor.exitVelocityScale,
      clearAngularVelocity: descriptor.clearAngularVelocity,
    });
  }

  const direction = normalizeVec3(descriptor.direction) ?? FORWARD;
  if (descriptor.type === 'fan') {
    return new FanObstacle({
      id: descriptor.id,
      kind: 'fan',
      enabled: descriptor.enabled,
      zone,
      direction,
      maxForce: descriptor.strength,
      falloff: descriptor.falloff,
      pulse: descriptor.pulse,
    });
  }

  return new ConveyorObstacle({
    id: descriptor.id,
    kind: 'conveyor',
    enabled: descriptor.enabled,
    zone,
    direction,
    targetSpeed: descriptor.strength,
    coupling: descriptor.coupling,
  });
}

export function createPad(descriptor: PadDescriptor): PadObstacle {
  return new PadObstacle({
    id: descriptor.id,
    kind: PAD_KINDS[descriptor.type],
    zone: descriptorZone(descriptor),
    strength: descriptor.strength,
    direction: descriptor.direction,
    maxSpeed: descriptor.maxSpeed,
    cooldownSeconds: descriptor.cooldownSeconds,
    enabled: descriptor.enabled,
  });
}

/** Static bumpers double as impulse pads; their restitution drives the bounce strength. */
export function createBumperPad(descriptor: StaticObstacle): PadObstacle | null {
  if (descriptor.type !== 'bumper') return null;
  return new PadObstacle({
    id: descriptor.id,
    kind: 'bumper',
    zone: descriptorZone(descriptor),
    strength: descriptor.restitution ?? 1,
    enabled: descriptor.enabled,
  });
}

export function createZone(descriptor: FieldObstacle | HazardObstacle): IZone {
  const bounds = descriptorBounds(descriptor);
  switch (descriptor.type) {
    case 'water':
      return new WaterZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 1, descriptor.resetPosition);
    case 'lava':
      return new LavaZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 2, descriptor.resetPosition);
    case 'void':
    case 'reset-zone':
      return new KillZone(descriptor.id, bounds, descriptor.penaltyStrokes ?? 1, descriptor.resetPosition);
    case 'gravity-zone':
      return new GravityZone(descriptor.id, bounds, descriptor.strength, descriptor.direction ?? DOWN);
    case 'magnet-zone':
      return new MagnetZone(descriptor.id, bounds, descriptor.strength, descriptor.repel ?? false);
  }
}

export function createRotatingConfig(descriptor: MovingObstacle): RotatingConfig | null {
  const kind = ROTATING_KINDS[descriptor.type];
  if (!kind || descriptor.motion.kind === 'translate') return null;
  const motion = descriptor.motion;
  return {
    id: descriptor.id,
    kind,
    center: { ...descriptor.transform.position },
    armLength: motion.armLength ?? Math.max(descriptor.size.x, descriptor.size.z) / 2,
    speed: motion.speed,
    phase: motion.phase,
    clockwise: motion.clockwise,
    swingAngle: motion.swingAngle,
    enabled: descriptor.enabled,
  };
}

export function createMoverConfig(descriptor: MovingObstacle): MoverConfig | null {
  const kind = MOVER_KINDS[descriptor.type];
  if (!kind || descriptor.motion.kind !== 'translate') return null;
  const motion = descriptor.motion;
  return {
    id: descriptor.id,
    kind,
    origin: { ...descriptor.transform.position },
    axis: { ...motion.axis },
    distance: motion.distance ?? 0,
    speed: Math.abs(motion.speed),
    phase: motion.phase,
    loop: motion.loop,
    pauseSeconds: motion.pauseSeconds,
    enabled: descriptor.enabled,
  };
}

export interface HoleObstacleRuntime {
  forces: BallObstacle[];
  pads: PadObstacle[];
  zones: IZone[];
  rotating: RotatingConfig[];
  movers: MoverConfig[];
}

/** Instantiates every runtime helper a hole descriptor asks for, grouped by system. */
export function buildHoleObstacleRuntime(hole: Hole): HoleObstacleRuntime {
  const runtime: HoleObstacleRuntime = { forces: [], pads: [], zones: [], rotating: [], movers: [] };

  for (const obstacle of hole.obstacles) {
    if (isForceObstacle(obstacle)) {
      runtime.forces.push(createForceObstacle(obstacle));
    } else if (isPadDescriptor(obstacle)) {
      runtime.pads.push(createPad(obstacle));
    } else if (isFieldObstacle(obstacle) || isHazardObstacle(obstacle)) {
      runtime.zones.push(createZone(obstacle));
    } else if (isMovingObstacle(obstacle)) {
      const rotating = createRotatingConfig(obstacle);
      if (rotating) runtime.rotating.push(rotating);
      const mover = createMoverConfig(obstacle);
      if (mover) runtime.movers.push(mover);
    } else {
      const bumper = createBumperPad(obstacle);
      if (bumper) runtime.pads.push(bumper);
    }
  }

  return runtime;
}
